import{_ as t,c as a,o as r,ag as n}from"./chunks/framework.ARG558ZT.js";const f=JSON.parse('{"title":"Reading and homework by track","description":"","frontmatter":{},"headers":[],"relativePath":"learner-guide/tracks.md","filePath":"learner-guide/tracks.md"}'),i={name:"learner-guide/tracks.md"};function o(s,e,d,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="reading-and-homework-by-track" tabindex="-1">Reading and homework by track <a class="header-anchor" href="#reading-and-homework-by-track" aria-label="Permalink to “Reading and homework by track”">​</a></h1><p><a href="./">Guide home</a> · <a href="./node-start.html">Current Node route</a> · <a href="./topics.html">Full topic mapping</a></p><p>These sequences reuse existing assignments. Reading readiness is lighter than implementation readiness: start a pure function, HTML document, item transform or lexical search as soon as its bounded contract makes sense. Before integrating later stages, satisfy their earlier observable behavior. Each linked specification supplies the exact negative cases; summaries here do not replace it. Keep revision/environment, expected/actual results, a failure→correction→retest and remaining uncertainty at every step.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to “Frontend”">​</a></h2><p><strong>Entry/readiness:</strong> basic files/browser use for F01; you can explain semantic labels and a native form before enhancing it. JS functions/promises become implementation prerequisites at F03, rather than prerequisites to reading HTML.</p><p>Read <a href="./../frontend/html-browser.html">HTML/browser</a> → <a href="./../senior_growth/A11y/">accessibility</a> → <a href="./../senior_growth/CSS/">CSS</a> → <a href="./../frontend/javascript.html">JavaScript</a> → <a href="./../frontend/typescript.html">TypeScript</a> → <a href="./../frontend/react.html">React</a> → <a href="./../frontend/next.html">Next/UI architecture</a>. The <a href="./../frontend/coverage-map.html">coverage map</a> links detailed lesson owners. Consult <a href="./../workbench/frontend/browser/">browser</a>, <a href="./../workbench/frontend/javascript/">JS</a>, <a href="./../workbench/frontend/typescript/">TS</a>, <a href="./../workbench/frontend/react/">React</a>, <a href="./../workbench/frontend/next/">Next</a> and <a href="./../workbench/frontend/architecture/">architecture</a> references after predicting their behavior.</p><table tabindex="0"><thead><tr><th>Order / homework</th><th>Implementation dependency and move-on criterion</th><th>Retain</th></tr></thead><tbody><tr><td><a href="./../practice/frontend/f01-document.html">F01</a></td><td>Basic HTML; no-JS search/dialog task, names, focus and recovery work</td><td>Actual keyboard/focus and no-JS observations</td></tr><tr><td><a href="./../practice/frontend/f02-layout.html">F02</a></td><td>F01; narrow/wide layout preserves long content and focus</td><td>Viewports, screenshots and layout failures</td></tr><tr><td><a href="./../practice/frontend/f03-javascript.html">F03</a></td><td>Working document plus functions/closures/promises; late work cannot overwrite intent</td><td>Controlled B-before-A schedule and cleanup</td></tr><tr><td><a href="./../practice/frontend/f04-typescript.html">F04</a></td><td>F03; malformed payloads reject and impossible states fail compile</td><td>Runtime negative cases and actual diagnostics</td></tr><tr><td><a href="./../practice/frontend/f05-react.html">F05</a></td><td>F01–04; stable drafts, truthful forms and effect cleanup</td><td>P-329 race/key/batching/closure failures and corrections</td></tr><tr><td><a href="./../practice/frontend/f06-next.html">F06</a></td><td>F05 + HTTP + server authority; explicit freshness and authorized mutations</td><td>UI/API allowed/denied results and ownership boundaries</td></tr></tbody></table><p><a href="./../practice/frontend-project.html#p-328">P-328</a> integrates URL filters, pages/selection, drafts, accessibility, localization and recovery into one management screen. <a href="./../practice/frontend-project.html#p-329">P-329</a> isolates React failures within it; <a href="./../practice/frontend-project.html#p-330">P-330</a> spans compile-time contracts and hostile runtime input. P-330 concepts begin at F04; F06 integrates them with server authority. Do not wait for the entire P-328 product before trying F01. Optional Redux, advanced typing, virtualization or custom widgets follow the primary flow and an observed need.</p><h2 id="node-databases-distributed-systems-and-deployment" tabindex="-1">Node, databases, distributed systems and deployment <a class="header-anchor" href="#node-databases-distributed-systems-and-deployment" aria-label="Permalink to “Node, databases, distributed systems and deployment”">​</a></h2><p><strong>Entry/readiness:</strong> trace promise/error/module behavior and operate a terminal. Follow <a href="./node-start.html">N-01–06</a> and then <a href="./../practice/backend-project.html#p-332">P-332</a>. Read modules 1, 2, 3, the relevant 4/5 sections, 11 and lifecycle sections of 10; these numbers intentionally differ from a numerical sweep.</p><p>For a service, read <a href="./../node-js/module-06-express-architecture.html">Express</a> → <a href="./../node-js/module-08-postgresql-mikroorm.html">PostgreSQL/MikroORM</a> → <a href="./../node-js/module-09-authentication-authorization.html">authentication/authorization</a>. Start the first validated use case before finishing every supplement. Use <a href="./../workbench/node-js/database/sql-queries.html">SQL queries</a>, <a href="./../workbench/node-js/backend/products-api.html">products API</a>, <a href="./../workbench/node-js/backend/session-app.html">session app</a> and <a href="./../workbench/node-js/backend/rest-contracts.html">REST contracts</a> only within their stated setup boundaries.</p><table tabindex="0"><thead><tr><th>Milestone</th><th>Prerequisites and move-on criterion</th><th>Retain</th></tr></thead><tbody><tr><td>P-332</td><td>Analyzer recommended; controlled workers stop admission/drain, strict byte framing and pipeline failures behave correctly</td><td>Exact schedules, abort identity, peak work, memory workload and natural process exit</td></tr><tr><td><a href="./../practice/backend-project.html#p-331">P-331</a></td><td>HTTP/validation + disposable SQL database + current identity; independent owner/tenant checks, transactional race/duplicate/rollback invariants and one upload <strong>or</strong> webhook ingress</td><td>Real DB state, safe HTTP results, negative/interleaving tests, authority diagram and lifecycle evidence</td></tr><tr><td>Service hardening</td><td>P-331 vertical slice; revisit <a href="./../node-js/module-10-production-ready-applications.html">lifecycle</a>, <a href="./../node-js/module-11-performance-diagnostics.html">diagnostics</a> and <a href="./../node-js/module-12-resilient-distributed-systems.html">distributed failures</a></td><td>Dependency outage, safe logs, admission/drain, uncertainty/idempotency decision</td></tr><tr><td><a href="./../practice/backend-project.html#p-333">P-333</a></td><td>Integrated frontend/API/DB plus <a href="./../node-js/container-deployment-lab.html">containers</a>, <a href="./../node-js/database-recovery.html">recovery</a>, <a href="./../node-js/release-artifact-compatibility.html">artifact compatibility</a>, <a href="./../node-js/full-stack-deployment.html">whole-stack runbook</a></td><td>Failed-candidate detection, exact artifact rollback, accepted-write preservation, isolated restore and shutdown</td></tr></tbody></table><p>The <a href="./../practice/node-js/">Node practice map</a> attaches every supplement to these projects. Cursor/date/retention/REST/secure-ingress practice deepens P-331. Durable jobs and shared limits need a real durability or multi-owner requirement. MongoDB, GraphQL, Redis, OIDC and alternative transports follow a stated comparison goal. AWS/Kubernetes are optional platform scope. Local container mechanics are not hosted authenticated-product completion.</p><h2 id="cs-foundations" tabindex="-1">CS foundations <a class="header-anchor" href="#cs-foundations" aria-label="Permalink to “CS foundations”">​</a></h2><p><strong>Entry/readiness:</strong> trace loops, arrays, reference mutation and basic TS. Explain one finite loop&#39;s progress before moving to recursion. Read <a href="./../cs-foundations/complexity-and-cost.html">cost</a> → <a href="./../cs-foundations/reasoning-and-recursion.html">reasoning/recursion</a> → <a href="./../cs-foundations/data-structures.html">structures</a> → <a href="./../cs-foundations/binary-search.html">binary search</a> → <a href="./../cs-foundations/sorting.html">sorting</a> → <a href="./../cs-foundations/trees-graphs-traversal.html">trees/graphs</a> → <a href="./../cs-foundations/priority-queues.html">priority queues</a>.</p><p>Use the <a href="./../workbench/cs-foundations/">CS workbench</a> after an independent trace. <a href="./../practice/cs-foundations/cost-and-search.html#cs-p01-cost-and-membership">CS-P01</a> membership costs → <a href="./../practice/cs-foundations/cost-and-search.html#cs-p02-lower-bound">CS-P02</a> half-open lookup → <a href="./../practice/cs-foundations/sorting.html">CS-P03</a> sort comparison → <a href="./../practice/cs-foundations/collections-and-queues.html#cs-p04-bounded-fifo">CS-P04</a> FIFO → <a href="./../practice/cs-foundations/dependency-explorer.html#cs-p05-note-dependency-explorer">CS-P05</a> explorer → <a href="./../practice/cs-foundations/dependency-explorer.html#cs-p06-priority-scheduler">CS-P06</a> scheduler.</p><p>These are recommended checkpoints, with concrete capability dependencies: search/sort need cost/reasoning; FIFO needs structure/ownership; explorer needs traversal; scheduler needs heap/FIFO invariants. An independent FIFO exercise need not wait for sorting mastery. Move on when small/empty/boundary cases, mutation policy, invariant and termination argument hold; retain operation counts before timings, fixed seeds and counterexamples. Cache/memoization are optional extensions after collection/identity contracts. Weighted paths, balanced trees, consensus and advanced DP are optional further depth, not hidden Node gates.</p><h2 id="python-and-applied-ai" tabindex="-1">Python and applied AI <a class="header-anchor" href="#python-and-applied-ai" aria-label="Permalink to “Python and applied AI”">​</a></h2><p><strong>Entry/readiness:</strong> basic programming is helpful; begin deterministic Python setup without a provider. You are ready for integration when you can parse a typed record, reject invalid input, await bounded I/O and name the owner that closes it.</p><p>Read <a href="./../python-for-ai/setup-and-basics.html">setup</a> → <a href="./../python-for-ai/typed-modules-and-errors.html">typed modules/errors</a> → <a href="./../python-for-ai/configuration-and-logging.html">configuration/logging</a> → <a href="./../python-for-ai/bounded-document-streams.html">bounded streams</a> → <a href="./../python-for-ai/async-http.html">async HTTP</a> → <a href="./../python-for-ai/fastapi-boundaries.html">FastAPI</a>; <a href="./../python-for-ai/deployment.html">deployment</a> follows a working service. Begin P-337 pure preparation during the first lessons; add DTOs, injected repository, lifespan and HTTP in that order. Its full acceptance additionally requires durable-adapter/restart and process evidence—an in-memory reference is insufficient.</p><p>Next use <a href="./../applied-ai/shared/">shared AI foundations</a> → <a href="./../applied-ai/rag/">RAG</a> → <a href="./../applied-ai/workflows/">workflows</a> → <a href="./../applied-ai/n8n/">n8n</a>. These guides link the detailed Python lessons in concept order. The <a href="./../practice/applied-ai/chapters/">chapter practice index</a> pairs detailed reading with bounded exercises; consult <a href="./../workbench/applied-ai/python/">Python reference sources</a> after predicting inputs/outcomes.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Minimum concepts / dependency</th><th>Observable exit and evidence</th></tr></thead><tbody><tr><td><a href="./../practice/ai-project.html#p-337">P-337</a></td><td>Typed Python → strict DTO → owned async/lifespan → HTTP</td><td>Invalid/oversize/foreign input denied, safe logging, real process shutdown; locked checks, source/runtime and durable restart observations</td></tr><tr><td><a href="./../practice/applied-ai/rag-assistant.html#rag-1-ingestion-and-lexical-baseline">RAG-1</a></td><td>Typed records/files, extraction and current ACL</td><td>Reconstruct exact spans; scoped lexical baseline; reject invalid input before provider calls</td></tr><tr><td><a href="./../practice/applied-ai/rag-assistant.html#rag-2-compatible-indexing-hybrid-and-reranking">RAG-2</a></td><td>RAG-1; embedding-space and index lifecycle</td><td>Same permitted corpus comparison, compatible versions, bounded ranking; keep labels/ranks/metrics and unavailable real-adapter gaps</td></tr><tr><td><a href="./../practice/applied-ai/rag-assistant.html#rag-3-checked-answer-and-abstention">RAG-3</a></td><td>Current span resolver, tokens/schema/streaming; <a href="./../applied-ai/rag/answering-and-failures.html">answer composition</a></td><td>Supported citations versus mere membership, honest abstention/unavailable/partial states; per-claim judgments and cancellation</td></tr><tr><td><a href="./../practice/applied-ai/rag-assistant.html#rag-4-evaluation-and-lifecycle">RAG-4</a></td><td>Prior RAG stages and independent evaluation set</td><td>Frozen comparison, revocation/delete/update/restore behavior; retain split/rubric and lifecycle records</td></tr><tr><td><a href="./../practice/applied-ai/resumable-workflow.html#wf-1-fixed-read-propose-validate">WF-1</a></td><td>Typed tools, current identity and bounded dispatch</td><td>Fixed read/propose; invalid routing causes zero disallowed I/O; call/effect counts</td></tr><tr><td><a href="./../practice/applied-ai/resumable-workflow.html#wf-2-artifacts-and-durable-approval">WF-2</a></td><td>WF-1; SQLite/CAS and immutable artifacts</td><td>Real restart, current source validation and exact-command approval binding; revision/denial/UI records</td></tr><tr><td><a href="./../practice/applied-ai/resumable-workflow.html#wf-3-receipt-and-interrupted-recovery">WF-3</a></td><td>WF-2; transaction/receipt semantics</td><td>Interrupted resume and duplicates yield one local effect; preserve command IDs, receipts and unknown-outcome reconciliation</td></tr><tr><td><a href="./../practice/applied-ai/resumable-workflow.html#wf-4-time-retries-budgets-and-evaluation">WF-4</a></td><td>Prior workflow stages</td><td>Limits survive restart, classified retries/cancel settle honestly; full attempt/usage/trace ledger</td></tr><tr><td><a href="./../practice/applied-ai/n8n-integration.html">N8N-P01 N-1 → N-4</a></td><td>N-1 item transforms first; JSON/HTTP/scoped service for N-2; failures/replay for N-3; operational record N-4</td><td>Actual engine/test-webhook, replay/no-duplicate-effect and subworkflow observations; separate workbench-only results</td></tr></tbody></table><p>P-334 spans RAG-1–4; P-335 spans WF-1–4 plus evaluation. The reading order places RAG first, but fixed tools need shared authority/state foundations rather than a completed RAG engine. <a href="./../applied-ai/n8n/integration.html">n8n integration</a> and <a href="./../applied-ai/n8n/operations.html">operations</a> become necessary as you connect the transform to a service. Keep workflows manual/test-only. Model theory/modalities, MCP, graphs/adaptation, ETL/Streamlit and cache/batch are optional after their relevant primary boundary; no training, paid model or hosted vector store is required to start.</p><h2 id="engineering-and-ai-assisted-development" tabindex="-1">Engineering and AI-assisted development <a class="header-anchor" href="#engineering-and-ai-assisted-development" aria-label="Permalink to “Engineering and AI-assisted development”">​</a></h2><p><strong>Entry/readiness:</strong> an owned small contract is enough for quality and P-336; shared state requires JS/React; measured performance requires a working flow; security requires HTTP/identity; delivery/architecture require an actual vertical slice. Read just the relevant guide first, then its detailed links.</p><table tabindex="0"><thead><tr><th>Order / increment</th><th>Read and consult</th><th>Move-on behavior and retained evidence</th></tr></thead><tbody><tr><td><a href="./../practice/engineering/e01.html">E01</a>, after F05</td><td><a href="./../engineering/state.html">State</a>, state workbench</td><td>Coherent normalized snapshots, account isolation, B-before-A safety; assertions plus UI/cleanup</td></tr><tr><td><a href="./../practice/engineering/e02.html">E02</a>, after working UI</td><td><a href="./../engineering/performance.html">Performance</a></td><td>One measured cause corrected without losing behavior; comparable repeated traces/cache/device conditions</td></tr><tr><td><a href="./../practice/engineering/e03.html">E03</a>, at P-330/P-331</td><td><a href="./../engineering/security.html">Security</a></td><td>Real operation denies foreign/stale/unsafe writes; safe HTTP/DB threat→test evidence</td></tr><tr><td><a href="./../practice/engineering/e04.html">E04</a>, can begin early</td><td><a href="./../engineering/quality.html">Quality</a></td><td>Detected baseline defect, negative controls for gates, justified refactor; exact diff/check results</td></tr><tr><td><a href="./../practice/engineering/e05.html">E05</a>, after artifact/DB basics</td><td><a href="./../engineering/delivery.html">Delivery</a></td><td>Local conflict recovery and same-artifact promotion; identities/compatibility and unsafe-rollback refusal</td></tr><tr><td><a href="./../practice/engineering/e06.html">E06</a>, after vertical slice</td><td><a href="./../engineering/design.html">Design</a></td><td>ADR/quality scenario/recovery rehearsal trace to real results; decision alternatives and actual handoff</td></tr><tr><td><a href="./../practice/engineering/e07.html">E07</a>, optional after primary path</td><td>Design specialist scope, <a href="./../workbench/engineering/specialists/">specialist references</a></td><td>One justified comparison, bounded failure/cleanup and adopt/defer decision</td></tr></tbody></table><p>Use <a href="./../workbench/engineering/">engineering workbench collections</a> and <a href="./../practice/engineering/">focused requirements</a> to deepen the same projects. E01–E07 are a recommended deepening order, not a rule to postpone tests/security until state/performance is finished. Testing/quality/patterns, Git/CI, design/requirements/estimation/onboarding/incident decisions and specialist comparisons are all mapped; organizational folders do not become separate courses.</p><p><a href="./../practice/ai-project.html#p-336">P-336</a>: read <a href="./../ai-assisted-engineering/issue-to-reviewed-change.html">issue→change</a> → <a href="./../ai-assisted-engineering/verification-and-permissions.html">verification/permissions</a> → <a href="./../ai-assisted-engineering/local-workflow-and-git.html">local Git workflow</a> → <a href="./../ai-assisted-engineering/traceability-and-evaluation.html">traceability</a>. Attempt a distinct real or labeled study issue; reproduce defect → minimal local correction → meaningful/fault checks → actual diff review → factual handoff. Retain requirement-to-check mapping and review outcome only if it actually occurred. This complements E04/E05; it does not require RAG or agents. Never push remotely.</p>',28)])])}const u=t(i,[["render",o]]);export{f as __pageData,u as default};
